// No inline buffer exists on the JVM; keep small values in primitive storage:
long[] keys = new long[1024];                 // dense, no per-element object

// or reuse one off-heap scratch buffer for the spill side:
ByteBuffer scratch = ByteBuffer.allocateDirect(64 * 1024);
scratch.clear().putLong(userId).putShort((short) flags);   // no per-value allocation

// and note that Integer caching is identity magic, not inlining:
Integer a = 127, b = 127;    // a == b (cache), but 128 would not be
